export const SITE_URL = "https://numerosemanas.es";

/**
 * Generated by src/app/opengraph-image.tsx. Pages that declare their own
 * `openGraph` object replace the inherited one, so they must list it again.
 */
export const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "NumeroSemanas: número de semana ISO, calendarios y festivos de España",
};

/** Years with a week list (/semanas/…) and a calendar (/calendario/…) page. */
export const FIRST_LISTED_YEAR = 2020;
export const LAST_LISTED_YEAR = 2035;

export function hasYearPages(year: number): boolean {
  return Number.isInteger(year) && year >= FIRST_LISTED_YEAR && year <= LAST_LISTED_YEAR;
}

/** Canonical URL of a year's week list (2026 lives at a dedicated slug). */
export function weeksYearHref(year: number): string {
  return year === 2026 ? "/semanas-2026" : `/semanas/${year}`;
}

/** Canonical URL of a year's calendar (2027 lives at a dedicated slug). */
export function calendarYearHref(year: number): string {
  return year === 2027 ? "/calendario-2027" : `/calendario/${year}`;
}

/**
 * Search-engine indexing is opt-in. Every environment (local, preview,
 * staging) stays out of search results unless SITE_INDEXING=enabled is set
 * at runtime. Set it only on the public production deployment at launch.
 */
export function isIndexingEnabled(): boolean {
  return process.env.SITE_INDEXING === "enabled";
}
